const _b = $('📥 Webhook Trigger').item.json.body;
if (_b.preApproved && _b.ytMeta) {
  let m = _b.ytMeta;
  if (typeof m === 'string') { try { m = JSON.parse(m); } catch(e) { m = null; } }
  if (m && m.title) {
    let desc = m.description || '';
    if (!String(desc).includes('#Shorts')) desc = String(desc).trimEnd() + '\n\n#Shorts';
    return [{ json: { ytTitle: m.title, ytDescription: desc, ytTags: m.tags } }];
  }
}
const raw = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';
let ytMeta;
try {
  const cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
  ytMeta = JSON.parse(cleaned);
  if (!ytMeta.title || !ytMeta.description || !ytMeta.tags) throw new Error('Campos incompletos');
} catch(e) {
  const phrase = $('📥 Webhook Trigger').item.json.body.phrase || '';
  ytMeta = {
    title: phrase.slice(0, 60).replace(/[\/\\:*?"<>|]/g, '').trim(),
    description: 'El proceso no se negocia.\n@bebetter.path ⚔️\n\n#Shorts',
    tags: 'bebetter,motivacion,disciplina,estoicismo,shorts,mindset'
  };
}
if (!ytMeta.description.includes('#Shorts')) {
  ytMeta.description = ytMeta.description.trimEnd() + '\n\n#Shorts';
}
return [{ json: { ytTitle: ytMeta.title, ytDescription: ytMeta.description, ytTags: ytMeta.tags } }];

const item = $input.item;
const isError = !!(item.json.error || item.json.status === 'failed');
return [{ json: {
  platform: 'YouTube',
  status: isError ? 'ERROR' : 'SUCCESS',
  videoId: isError ? null : (item.json.uploadId || item.json.id || null),
  errorDetails: isError ? (item.json.error?.message || JSON.stringify(item.json)) : null,
  timestamp: new Date().toISOString()
}}];

const IG_HASHTAGS = ["#BeBetterPath", "#Estoicismo", "#Disciplina", "#Mentalidad", "#Motivacion", "#Mindset", "#Estoico", "#DesarrolloPersonal"];
const _b = $('📥 Webhook Trigger').item.json.body;
if (_b.preApproved && _b.captionIG) {
  return [{ json: { message1: _b.phrase || '', message2: _b.captionIG } }];
}
const caption = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const phrase = $('📥 Webhook Trigger').item.json.body.phrase || '';
const captionWithTags = caption.trim() + '\n\n' + IG_HASHTAGS.join(' ');
return [{ json: { message1: phrase, message2: captionWithTags } }];

const b = $('📥 Webhook Trigger').item.json.body;
const meta = $('🎬 Parse YT Meta').item.json;
const caption = `🎬 ${meta.ytTitle}\n\n${b.phrase || ''}`;
return [{ json: { caption, ytTitle: meta.ytTitle } }];

const j = $json;
const cq = j.callback_query || j.callbackQuery || (j.body && j.body.callback_query) || j;
const data = String(cq.data || '');
const [dec, execId] = data.split(':');
return [{ json: { approved: dec === '1', execId, callbackQueryId: cq.id } }];

const s = JSON.stringify($input.item.json);
const m = s.match(/https?:\/\/[^"'\\ ]*webhook-waiting\/\d+\?signature=[a-f0-9]+/);
const pc = $('🔓 Parse Callback').item.json;
return [{ json: { resumeUrl: m ? m[0] : null, approved: pc.approved, callbackQueryId: pc.callbackQueryId } }];

const j = $json;
const cq = j.callback_query || j.callbackQuery || (j.body && j.body.callback_query) || j;
const data = String(cq.data || '');
const [action, queueId] = data.split(':');
const status = action === 'a' ? 'approved' : 'rejected';
return [{ json: { action, queueId, status, callbackQueryId: cq.id } }];

const m = $json.message || {};
const replyToId = m.reply_to_message ? m.reply_to_message.message_id : null;
const newCaption = String(m.text || '');
const chatId = m.chat ? m.chat.id : null;
return [{ json: { replyToId, newCaption, chatId } }];

const rows = $('📥 Leer cola (/cola)').all().map(i => i.json);
const cfgRows = $('📅 Leer cadencia (/cola)').all().map(i => i.json);
const cfg = {};
for (const r of cfgRows) { if (r.key) cfg[String(r.key).trim()] = String(r.value == null ? '' : r.value).trim(); }
const times = (cfg.cadence_times || '').split(',').map(s => s.trim()).filter(Boolean);
const tz = cfg.timezone || 'America/Bogota';

const approved = rows
  .filter(r => String(r.status || '').trim() === 'approved' && !String(r.publishedAt || '').trim())
  .sort((a, b) => String(a.createdAt || '').localeCompare(String(b.createdAt || '')));

const trig = $('Telegram Trigger').first().json;
const chatId = (trig.message && trig.message.chat && trig.message.chat.id) || 8739538908;

function tzOffsetMinutes(tz, date) {
  const dtf = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour12: false, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
  const p = {}; for (const x of dtf.formatToParts(date)) p[x.type] = x.value;
  const asUTC = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second);
  return Math.round((asUTC - date.getTime()) / 60000);
}
function projectSlots(n, times, tz, now) {
  const hours = times.map(t => Number(String(t).split(':')[0])).filter(h => Number.isInteger(h) && h >= 0 && h <= 23).sort((a, b) => a - b);
  if (!hours.length || !n) return [];
  const off = tzOffsetMinutes(tz, now);
  const wall = new Date(now.getTime() + off * 60000);
  const Y = wall.getUTCFullYear(), Mo = wall.getUTCMonth(), D = wall.getUTCDate(), ch = wall.getUTCHours(), cm = wall.getUTCMinutes();
  const slots = [];
  for (let day = 0; slots.length < n && day < 90; day++) {
    for (const h of hours) {
      if (day === 0 && (h < ch || (h === ch && cm > 0))) continue;
      slots.push({ dayOffset: day, hour: h, etaMs: Date.UTC(Y, Mo, D + day, h, 0, 0) - off * 60000 });
      if (slots.length >= n) break;
    }
  }
  return slots;
}
function label(s, tz) {
  if (!s) return '—';
  const t = String(s.hour).padStart(2, '0') + ':00';
  if (s.dayOffset === 0) return 'Hoy ' + t;
  if (s.dayOffset === 1) return 'Mañana ' + t;
  const ds = new Date(s.etaMs).toLocaleDateString('es-CO', { weekday: 'short', day: 'numeric', timeZone: tz });
  return ds + ' ' + t;
}

const slots = projectSlots(approved.length, times, tz, new Date());
let msg;
if (!approved.length) {
  msg = '✅ *Cola de aprobados*\n\nNo hay videos aprobados esperando publicación.';
} else if (!times.length) {
  msg = '⚠️ Hay ' + approved.length + ' aprobado(s) pero *no hay cadencia configurada* — no se publicarán hasta definir horas en la app.';
} else {
  const lines = approved.map((r, i) => {
    const ph = String(r.phrase || '').replace(/\s+/g, ' ').slice(0, 45);
    return (i + 1) + '. "' + ph + '" → *' + label(slots[i], tz) + '*';
  });
  msg = '📋 *Próximas publicaciones* (' + approved.length + ' en cola)\n\n' + lines.join('\n') + '\n\n_Cadencia: ' + times.join(', ') + ' · ' + tz + '_';
}
return [{ json: { chatId, msg } }];

